458	LiaStarExtension::Subsolver& LiaStarExtension::getSubsolver(Node lambda)
459	{
460	  // Return the persistent incremental subsolver for `lambda`, creating and
461	  // seeding it on first use. It is used by the lazy strategy to enumerate the
462	  // convex cells of the predicate's satisfying region.
463	  auto it = d_subsolvers.find(lambda);
464	  if (it != d_subsolvers.end())
465	  {
466	    return it->second;
467	  }
468	  Subsolver& sub = d_subsolvers[lambda];
469	
470	  Options subOptions;
471	  // we read the model below to construct the disjunct.
472	  subOptions.write_smt().produceModels = true;
473	  sub.engine = std::make_unique<SolverEngine>(d_nm, &subOptions);
474	  sub.engine->setIsInternalSubsolver();
475	  LogicInfo info("QF_LIA");
476	  sub.engine->setLogic(info);
477	  sub.engine->setOption("incremental", "true");
478	
479	  // The base assertion is the membership predicate (with ites and negations
480	  // eliminated) conjoined with the non-negativity of the lambda's variables.
481	  Node base = LiaStarUtils::removeItesAndNots(lambda[1], &d_env);
482	  std::vector<Node> conjuncts{base};
483	  for (Node var : lambda[0])
484	  {
485	    conjuncts.push_back(d_nm->mkNode(Kind::GEQ, var, d_zero));
486	  }
487	  base =
488	      conjuncts.size() == 1 ? conjuncts[0] : d_nm->mkNode(Kind::AND, conjuncts);
489	
490	  // The lambda's bound variables appear free in `base`. A formula with free
491	  // (bound) variables cannot be asserted to a subsolver, so we replace them
492	  // with fresh free constants and remember the mapping so the disjunct built
493	  // from the model can be substituted back into bound-variable space.
494	  for (Node var : lambda[0])
495	  {
496	    if (var.getKind() == Kind::BOUND_VARIABLE)
497	    {
498	      sub.from.push_back(var);
499	      sub.to.push_back(d_nm->mkDummySkolem("liastar", var.getType()));
500	    }
501	  }
502	  if (!sub.from.empty())
503	  {
504	    base = base.substitute(
505	        sub.from.begin(), sub.from.end(), sub.to.begin(), sub.to.end());
506	  }
507	  sub.base = base;
508	  sub.engine->assertFormula(base);
509	  return sub;
510	}
