566	LiaStarExtension::getCones(
567	    Node n, const std::vector<std::pair<std::vector<std::string>, Node>>& pairs)
568	{
569	  // Eager path: build a cone for every DNF disjunct (`pairs`) and accumulate
570	  // the star constraints over all of them. Returns (cones, starConstraints):
571	  // the cones (paired with their predicate node) are used to build the
572	  // membership encoding for the debug trace, and starConstraints is the star
573	  // encoding that becomes the reduction lemma.
574	  std::vector<std::pair<Node, Cone<Integer>>> cones;
575	  std::vector<Node> vec(n.begin() + 1, n.end());
576	  size_t dimension = vec.size();
577	  std::vector<std::pair<Vector, std::vector<Vector>>> lambdas;
578	  std::vector<Node> starConstraints;
579	
580	  for (size_t i = 0; i < pairs.size(); i++)
581	  {
582	    const std::pair<std::vector<std::string>, Node>& pair = pairs[i];
583	    Trace("liastar-ext") << "---------------------------" << std::endl;
584	    Trace("liastar-ext") << "Cone for node " << i << std::endl
585	                         << pair.second << std::endl;
586	
587	    Cone<Integer> cone = LiaStarUtils::buildCone(dimension, pair.first);
588	    if (LiaStarUtils::isEmptyCone(cone))
589	    {
590	      // an infeasible disjunct contributes nothing to the star
591	      Trace("liastar-ext") << "empty cone" << std::endl;
592	      continue;
593	    }
594	
595	    for (const auto& generator : getConeGenerators(cone, dimension))
596	    {
597	      Trace("liastar-ext") << toString(generator) << std::endl;
598	      // Build the star encoding of this generator over fresh skolems (the
599	      // constraints are asserted at the top level, not under a quantifier) and
600	      // accumulate its side constraints and its (point, rays) contribution.
601	      std::vector<Node> vars, constraints;
602	      Vector point;
603	      std::vector<Vector> rays;
604	      LiaStarUtils::getGeneratorBody(dimension,
605	                                     generator,
606	                                     cone.getHilbertBasis(),
607	                                     /*star=*/true,
608	                                     /*useSkolems=*/true,
609	                                     d_nm,
610	                                     vars,
611	                                     constraints,
612	                                     point,
613	                                     rays);
614	      starConstraints.insert(
615	          starConstraints.end(), constraints.begin(), constraints.end());
616	      lambdas.push_back({point, rays});
617	    }
618	    cones.push_back({pair.second, cone});
619	  }
620	
621	  // The star vector equals the sum of every cone's contribution.
622	  std::vector<Node> sums = buildSumConstraints(d_nm, d_zero, vec, lambdas);
623	  starConstraints.insert(starConstraints.end(), sums.begin(), sums.end());
624	
625	  return std::make_pair(cones, starConstraints);
626	}
